import { explorations } from '../data/projects.js';
import { sectionLabel, placeholder } from './shared.js';
export function Exploration() { return `<section id="exploration" class="exploration section" aria-labelledby="exploration-title"><div class="container">${sectionLabel('04','EXPLORATION')}<div class="exploration-grid"><div class="exploration-intro"><h2 id="exploration-title" class="reveal">Always <br><span class="soft-text">in orbit.</span></h2><p class="reveal">Questions, experiments, and<br>the occasional unexpected discovery.</p><div class="orbital-diagram reveal" aria-hidden="true"><div class="diagram-ring"></div><div class="diagram-ring"></div><div class="diagram-ring"></div><span class="diagram-center">+</span><span class="diagram-dot"></span></div><div class="reveal">${placeholder('EXPLORATION · PLACEHOLDER')}</div></div><div class="timeline">${explorations.map(e=>`<details class="timeline-entry reveal"><summary><span class="timeline-node"></span><div class="timeline-meta"><span>${e.type}</span><span>NOTE / ${e.number}</span></div><div class="timeline-title"><h3>${e.title}</h3><span class="expand-symbol" aria-hidden="true"></span></div><span class="entry-status">CONTENT TO COME</span></summary><div class="timeline-body"><p>${e.description}</p><p>This is a reserved space for a future ${e.type.toLowerCase()} entry.</p></div></details>`).join('')}</div></div></div></section>`; }
